import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import{World}from'../world.js';import{floodCells}from'../architecture.js';import{physicalBindings}from'../physical-lore.js';
const raw=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url))),world=new World(raw),rooms=world.data.scenes.filter(r=>r.architecture?.campaign);
test('campaign furniture preserves authored action and enemy approaches, arrivals and current exits',()=>{assert.equal(rooms.length,world.data.scenes.filter(s=>s.household).length);for(const r of rooms){const seen=floodCells(r.floor,r.arrive);assert.equal(r.floor[r.arrive[1]][r.arrive[0]],'.',r.key+' arrival');const source=raw.scenes.find(s=>s.location===r.location)||r;for(const o of [...source.objects.filter(o=>o.type!=='portal'),...r.objects.filter(o=>o.type==='portal'),...r.doors])for(const p of o.xy?[o.xy]:(o.enemies||[]).map(e=>e[1]))assert.ok([-1,0,1].some(dx=>[-1,0,1].some(dy=>seen.has((p[0]+dx)+','+(p[1]+dy)))),r.key+' '+o.type);for(const o of r.objects.filter(o=>o.furnishingId))assert.ok(seen.has(o.xy.join(',')),r.key+' inspection');for(const b of (r.household?.furnishings.filter(o=>![16,18].includes(o.furniture)).map(o=>o.footprint)||r.blocks||[]))for(let y=b.y;y<b.y+b.h;y++)for(let x=b.x;x<b.x+b.w;x++)assert.equal(r.floor[y][x],'#');}});
test('all campaign exits meet a shell boundary and duplicate floor doors are consolidated',()=>{for(const r of rooms){for(const d of r.doors){if(d.architecturalKind==='stairs')continue;assert.ok(d.wallMounted);const[x,y]=d.xy,[dx,dy]=Array.isArray(d.wallSide)?d.wallSide:({north:[0,-1],south:[0,1],west:[-1,0],east:[1,0]})[d.wallSide];assert.ok(!r.architecture.outline.some(span=>span.y===y+dy&&x+dx>=span.left&&x+dx<=span.right),r.key+' exit on shell');}for(const o of r.objects.filter(o=>o.sharedDoor))assert.ok(r.doors.some(d=>d.xy.join(',')===o.xy.join(',')));}});
test('physical lore placements stay reachable and clear of all furniture in the rebuilt rooms',()=>{for(const p of physicalBindings(world)){const r=world.scenes.get(p.physicalLocation),seen=floodCells(r.floor,r.arrive);assert.ok(seen.has(p.xy.join(',')));assert.ok(!r.blocks?.some(b=>p.xy[0]>=b.x&&p.xy[0]<b.x+b.w&&p.xy[1]>=b.y&&p.xy[1]<b.y+b.h));}});
test('restoring an old save inside a new furniture footprint moves to free floor without losing progress',()=>{const room=rooms.find(r=>r.key==='inn'),b=room.household.furnishings.find(o=>o.furniture===0).footprint,s=JSON.parse(world.save());s.scene=room.location;s.x=b.x+.5;s.y=b.y+.5;s.gold=271;world.restore(s);assert.ok(world.walkable(world.state.x,world.state.y));assert.equal(world.state.gold,271);});
test('building registry binds room identity, footprint and available exterior entrances',()=>{assert.equal(world.data.buildingRegistry.length,rooms.length);for(const b of world.data.buildingRegistry){assert.ok(b.footprint.length);assert.ok(b.entrances.length);for(const link of b.exteriorLinks)assert.ok(world.scenes.has(link.location));}assert.ok(world.data.buildingRegistry.find(b=>b.key==='home').exteriorLinks.length);});
